const EXPORTUNITY_MARKETPLACE_ROUTE_CATEGORIES = new Set(
  EXPORTUNITY_PARENT_MARKETPLACE_CATEGORIES.map((category) => category.id),
);

function getExportunityMarketplacePathCategory(): string | null {
  if (typeof window === "undefined") return null;
  const match = window.location.pathname.match(/^\/marketplace\/([^/?#]+)/);
  const category = normalizeCategorySlug(match?.[1]);
  if (!category || !EXPORTUNITY_MARKETPLACE_ROUTE_CATEGORIES.has(category)) {
    return null;
  }
  return category;
}

