function normalizeCadastreStatus(value: unknown) {
  return String(value || "")
    .trim()
    .toUpperCase();
}

function cadastreStatusToPermitStatus(
  status: unknown,
): "active" | "pending" | "suspended" {
  const normalized = normalizeCadastreStatus(status);
  if (normalized === "VERIFIED") return "active";
  if (normalized === "INACTIVE") return "suspended";
  return "pending";
}

function cadastreStatusToMineVerification(
  status: unknown,
): "verified" | "pending" {
  return normalizeCadastreStatus(status) === "VERIFIED"
    ? "verified"
    : "pending";
}

function makeFallbackPermitPolygon(
  lat: number,
  lng: number,
  delta = 0.04,
): Array<[number, number]> {
  return [
    [lat + delta, lng - delta],
    [lat + delta, lng + delta],
    [lat - delta, lng + delta],
    [lat - delta, lng - delta],
  ];
}

