function extractConciergeJsonCandidate(raw: string): string | null {
  const trimmed = raw.trim();
  if (!trimmed) return null;

  const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced?.[1]) return fenced[1].trim();

  const withoutPrefix = trimmed.replace(/^json\s*/i, "").trim();
  if (withoutPrefix.startsWith("{") || withoutPrefix.startsWith("["))
    return withoutPrefix;

  const firstBrace = withoutPrefix.indexOf("{");
  const lastBrace = withoutPrefix.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return withoutPrefix.slice(firstBrace, lastBrace + 1);
  }

  return null;
}

function parseConciergePayloadFromText(
  text: string,
): Record<string, unknown> | null {
  const candidate = extractConciergeJsonCandidate(text);
  if (!candidate) return null;
  try {
    const parsed = JSON.parse(candidate);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed))
      return null;
    return parsed as Record<string, unknown>;
  } catch {
    return null;
  }
}

function getConciergeMessageText(text: string): string {
  const payload = parseConciergePayloadFromText(text);
  const message = payload?.message;
  if (typeof message === "string" && message.trim()) return message;
  return text;
}

function trimDataUrlPreview(dataUrl: string) {
  return /^data:image\//i.test(String(dataUrl || "").trim());
}

function isFiniteMapPoint(point: unknown): point is [number, number] {
  return (
    Array.isArray(point) &&
    point.length === 2 &&
    Number.isFinite(Number(point[0])) &&
    Number.isFinite(Number(point[1]))
  );
}

function LocationUpdater({
  position,
  zoom,
  useMap,
}: {
  position: [number, number];
  zoom?: number;
  useMap: () => any;
}) {
  const map = useMap();
  useEffect(() => {
    if (!isFiniteMapPoint(position)) return;
    const nextZoom = typeof zoom === "number" ? zoom : map.getZoom();
    map.setView([Number(position[0]), Number(position[1])], nextZoom, { animate: true });
  }, [map, position, zoom]);
  return null;
}

function MapFitBounds({
  points,
  paddingPx = 48,
  maxZoom = 14,
  useMap,
  L,
}: {
  points: Array<[number, number]> | null;
  paddingPx?: number;
  maxZoom?: number;
  useMap: () => any;
  L: any;
}) {
  const map = useMap();
  useEffect(() => {
    if (!points || points.length === 0) return;
    const latLngs = points
      .map((p) =>
        isFiniteMapPoint(p) ? L.latLng(Number(p[0]), Number(p[1])) : null,
      )
      .filter(Boolean) as any[];
    if (latLngs.length === 0) return;
    const bounds = L.latLngBounds(latLngs);
    if (!bounds.isValid()) return;
    map.fitBounds(bounds, {
      padding: L.point(paddingPx, paddingPx),
      animate: true,
      maxZoom,
    });
  }, [map, points, paddingPx, maxZoom, L]);
  return null;
}

function MapResizer({
  depsKey,
  useMap,
}: {
  depsKey: string;
  useMap: () => any;
}) {
  const map = useMap();
  useEffect(() => {
    const id = window.setTimeout(() => {
      try {
        map.invalidateSize();
      } catch {
        // ignore
      }
    }, 80);
    return () => window.clearTimeout(id);
  }, [map, depsKey]);
  return null;
}

function MapAutoSizer({
  depsKey,
  useMap,
}: {
  depsKey: string;
  useMap: () => any;
}) {
  const map = useMap();

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (typeof (window as any).ResizeObserver !== "function") return;
    const container = map?.getContainer?.();
    if (!container) return;

    let raf: number | null = null;
    let lastAt = 0;

    const trigger = () => {
      try {
        map.invalidateSize();
      } catch {
        // ignore
      }
    };

    const ro = new (window as any).ResizeObserver(() => {
      const now = Date.now();
      if (now - lastAt < 80) return;
      lastAt = now;
      if (raf != null) cancelAnimationFrame(raf);
      raf = requestAnimationFrame(trigger);
    });

    ro.observe(container);
    const warmup = window.setTimeout(trigger, 120);

    return () => {
      window.clearTimeout(warmup);
      if (raf != null) cancelAnimationFrame(raf);
      ro.disconnect();
    };
  }, [map, depsKey]);

  return null;
}

function MapViewportFocus({
  target,
  useMap,
}: {
  target:
    | {
        key: string;
        position: [number, number];
        zoom?: number;
      }
    | null;
  useMap: () => any;
}) {
  const map = useMap();
  const lastKeyRef = useRef<string | null>(null);

  useEffect(() => {
    if (!target) return;
    if (lastKeyRef.current === target.key) return;
    lastKeyRef.current = target.key;
    const currentZoom = Number(map?.getZoom?.() || 6);
    const nextZoom =
      typeof target.zoom === "number" ? target.zoom : Math.max(currentZoom, 7);
    try {
      map.flyTo(target.position, nextZoom, {
        animate: true,
        duration: 0.6,
      });
    } catch {
      try {
        map.setView(target.position, nextZoom, { animate: true });
      } catch {
        // ignore map focus failures
      }
    }
  }, [map, target]);

  return null;
}

function ReelsMedia({
  videoUrl,
  imageUrl,
}: {
  videoUrl: string | null;
  imageUrl: string;
}) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  useEffect(() => {
    if (!videoUrl) return;
    const container = containerRef.current;
    const video = videoRef.current;
    if (!container || !video) return;

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!videoRef.current) continue;
          if (entry.isIntersecting && entry.intersectionRatio >= 0.6) {
            videoRef.current.play().catch(() => {
              // Autoplay may be blocked; user can tap to play.
            });
          } else {
            videoRef.current.pause();
          }
        }
      },
      { threshold: [0, 0.25, 0.5, 0.6, 0.75, 1] },
    );

    observer.observe(container);
    return () => observer.disconnect();
  }, [videoUrl]);

  return (
    <div ref={containerRef} className="absolute inset-0">
      {videoUrl ? (
        <video
          ref={videoRef}
          className="absolute inset-0 h-full w-full object-cover"
          src={videoUrl}
          poster={imageUrl}
          muted
          loop
          playsInline
          preload="metadata"
          onClick={() => {
            const v = videoRef.current;
            if (!v) return;
            if (v.paused) {
              v.play().catch(() => {
                // ignore
              });
            } else {
              v.pause();
            }
          }}
        />
      ) : (
        <img
          src={imageUrl}
          alt=""
          className="absolute inset-0 h-full w-full object-cover"
        />
      )}
    </div>
  );
}

function normalizeForMatch(value: unknown): string {
  return String(value ?? "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "");
}

