function hashStringBasic(value: string): number {
  let hash = 0;
  for (let index = 0; index < value.length; index += 1) {
    hash = (hash * 31 + value.charCodeAt(index)) | 0;
  }
  return Math.abs(hash);
}

function resolveWholesaleSellerMapPosition(
  shop: any,
  opts?: {
    nationalCoverage?: boolean;
    index?: number;
  },
): [number, number] | null {
  const rawLat = parseFloat(shop?.latitude?.toString() || "");
  const rawLng = parseFloat(shop?.longitude?.toString() || "");
  const hasRawCoords =
    Number.isFinite(rawLat) &&
    Number.isFinite(rawLng) &&
    Math.abs(rawLat) <= 90 &&
    Math.abs(rawLng) <= 180;

  const locationCorpus = normalizeForMatch(
    [
      shop?.shopName,
      shop?.streetAddress,
      shop?.cityName,
      shop?.regionName,
      shop?.countryName,
      shop?.description,
      ...(Array.isArray(shop?.products)
        ? shop.products.flatMap((product: any) => [
            product?.shortDescription,
            product?.description,
            ...(Array.isArray(product?.tags) ? product.tags : []),
          ])
        : []),
    ]
      .filter(Boolean)
      .join(" "),
  );

  const hintedLocation =
    WHOLESALE_LOCATION_HINTS.find((entry) =>
      entry.matchers.some((matcher) =>
        locationCorpus.includes(normalizeForMatch(matcher)),
      ),
    ) || null;

  const rawLooksLikeAbidjan =
    hasRawCoords &&
    rawLat >= 5.05 &&
    rawLat <= 5.6 &&
    rawLng >= -4.25 &&
    rawLng <= -3.75;

  if (hasRawCoords && (!opts?.nationalCoverage || !hintedLocation || !rawLooksLikeAbidjan)) {
    return [rawLat, rawLng];
  }

  if (!hintedLocation) {
    return hasRawCoords ? [rawLat, rawLng] : null;
  }

  const seed = hashStringBasic(
    `${shop?.id || shop?.shopName || locationCorpus}:${opts?.index ?? 0}`,
  );
  const latOffset = ((seed % 11) - 5) * 0.024;
  const lngOffset = (((Math.floor(seed / 11) % 11) - 5) * 0.028) / 1.35;

  return [
    Number((hintedLocation.center[0] + latOffset).toFixed(6)),
    Number((hintedLocation.center[1] + lngOffset).toFixed(6)),
  ];
}

function normalizeCurrencyCode(value: unknown): Currency {
  const upper = String(value ?? "").toUpperCase();
  if (
    upper === "USD" ||
    upper === "EUR" ||
    upper === "GBP" ||
    upper === "XOF" ||
    upper === "GHS" ||
    upper === "NGN" ||
    upper === "AED"
  ) {
    return upper as Currency;
  }
  return "XOF";
}

function normalizeCategorySlug(value: unknown): string | null {
  const raw = String(value ?? "").trim();
  if (!raw) return null;
  const slug = raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || null;
}

function safeLocalStorageGet(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeLocalStorageSet(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // ignore storage errors (private mode/quota)
  }
}

async function readImageFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = typeof reader.result === "string" ? reader.result : "";
      if (!result) {
        reject(new Error("Image attachment could not be read."));
        return;
      }
      resolve(result);
    };
    reader.onerror = () =>
      reject(new Error("Image attachment could not be read."));
    reader.readAsDataURL(file);
  });
}

function getMarketplaceCategory(product: any): string | null {
  return (
    normalizeCategorySlug(product?.categorySlug) ||
    normalizeCategorySlug(product?.categoryName) ||
    normalizeCategorySlug(product?.category?.slug) ||
    null
  );
}

function getCartCategorySlug(product: any, isGoldTenant: boolean): string | null {
  return (
    (isGoldTenant ? normalizeCategorySlug(getGoldCategory(product)) : null) ||
    getMarketplaceCategory(product)
  );
}

function getCartItemCategorySlug(item: any): string | null {
  const explicit = normalizeCategorySlug(item?.categorySlug);
  if (explicit) return explicit;

  const text = normalizeForMatch(
    `${item?.name || ""} ${item?.categoryName || ""} ${item?.categorySlug || ""}`,
  );
  const looksLikeCertifiedGold =
    /\b(stamped|piece|bar)\b/.test(text) ||
    text.includes("lingot") ||
    text.includes("certifie") ||
    text.includes("certified");
  const goldContext =
    /\b(gold|or)\b/.test(text) ||
    text.includes("stamped") ||
    text.includes("certifie") ||
    text.includes("certified");

  return looksLikeCertifiedGold && goldContext ? "stamped" : null;
}

function parseProductAttributes(product: any): Record<string, any> | null {
  const raw = product?.attributes;
  if (!raw) return null;
  if (typeof raw === "object") return raw as Record<string, any>;
  if (typeof raw !== "string") return null;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object"
      ? (parsed as Record<string, any>)
      : null;
  } catch {
    return null;
  }
}

function getGoldCategory(product: any): GoldCategorySlug | null {
  const attrs = parseProductAttributes(product) || {};
  const metadata =
    product?.metadata && typeof product.metadata === "object"
      ? product.metadata
      : {};
  const explicitGoldCategory = normalizeCategorySlug(
    product?.bdoGoldCategory ||
      product?.goldCategory ||
      attrs?.bdoGoldCategory ||
      attrs?.goldCategory ||
      attrs?.category ||
      (metadata as any)?.bdoGoldCategory ||
      (metadata as any)?.goldCategory ||
      (metadata as any)?.category,
  );
  if (
    explicitGoldCategory === "dore" ||
    explicitGoldCategory === "stamped" ||
    explicitGoldCategory === "jewelry" ||
    explicitGoldCategory === "gold-art"
  ) {
    return explicitGoldCategory;
  }

  const rawSlug = normalizeForMatch(
    product?.categorySlug ||
      attrs?.categorySlug ||
      attrs?.category ||
      (metadata as any)?.categorySlug ||
      (metadata as any)?.category,
  );
  const canonical = rawSlug ? rawSlug.replace(/[\s_]+/g, "-") : "";

  const categoryName = normalizeForMatch(product?.categoryName);
  const name = normalizeForMatch([product?.name, product?.title].filter(Boolean).join(" "));
  const description = normalizeForMatch(
    [product?.description, product?.shortDescription, attrs?.description, (metadata as any)?.description]
      .filter(Boolean)
      .join(" "),
  );
  const text = `${canonical || rawSlug || ""} ${categoryName} ${name} ${description}`.trim();

  const looksLikeGoldArt =
    text.includes("gold-art") ||
    text.includes("gold art") ||
    text.includes("objet d art") ||
    text.includes("objet d'art") ||
    text.includes("heritage") ||
    text.includes("bust") ||
    text.includes("buste") ||
    text.includes("medallion") ||
    text.includes("medaillon") ||
    text.includes("relief") ||
    text.includes("ceremonial") ||
    text.includes("sculpt") ||
    text.includes("statue") ||
    text.includes("statuette") ||
    text.includes("mask") ||
    text.includes("masque") ||
    text.includes("artifact") ||
    text.includes("object");

  const looksLikeJewelry =
    text.includes("jewel") ||
    text.includes("bijou") ||
    text.includes("ring") ||
    text.includes("bracelet") ||
    text.includes("chain") ||
    text.includes("chaine") ||
    text.includes("pendant") ||
    text.includes("pendentif") ||
    text.includes("earring");

  if (canonical) {
    if (canonical === "goldart" || canonical === "gold-art") return "gold-art";
    if (canonical === "dore" || canonical === "stamped")
      return canonical as GoldCategorySlug;

    // If the product was categorized as jewelry but looks like a museum/heritage object,
    // treat it as Gold Art so it appears in the correct rail (common mis-categorization).
    if (canonical === "jewelry")
      return looksLikeGoldArt ? "gold-art" : "jewelry";
  }

  if (looksLikeGoldArt) return "gold-art";
  if (looksLikeJewelry) return "jewelry";

  const looksLikeGold =
    text.includes("gold") ||
    text.includes("dore") ||
    text.includes("dor") ||
    text.includes("karat") ||
    text.includes("22k") ||
    text.includes("bullion") ||
    categoryName.includes("mineral");
  if (!looksLikeGold) return null;

  if (text.includes("dore")) return "dore";
  if (
    text.includes("stamp") ||
    text.includes("piece") ||
    text.includes("lingot") ||
    text.includes("ingot") ||
    text.includes("bar") ||
    text.includes("bullion") ||
    (text.includes("certifie") && !looksLikeJewelry)
  )
    return "stamped";

  return "stamped";
}

function toNumber(value: unknown): number {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function getProductWeightGrams(product: any): number {
  const attrs = parseProductAttributes(product);
  const directCandidates = [
    product?.weightGrams,
    product?.weight_grams,
    product?.grams,
    attrs?.weightGrams,
    attrs?.weight_grams,
    attrs?.grams,
  ];
  for (const candidate of directCandidates) {
    const grams = toNumber(candidate);
    if (grams > 0) return grams;
  }

  const weight = toNumber(product?.weight ?? attrs?.weight);
  if (weight > 0) {
    const unit = normalizeForMatch(
      product?.weightUnit ?? attrs?.weightUnit ?? attrs?.weight_unit,
    );
    if (unit === "kg" || unit === "kilogram" || unit === "kilograms")
      return weight * 1000;
    return weight;
  }

  const haystack = `${product?.name || ""} ${product?.description || ""} ${product?.categoryName || ""}`;
  const match = haystack.match(/(\d+(?:[.,]\d+)?)\s*(kg|g)\b/i);
  if (!match) return 0;
  const value = Number.parseFloat(match[1].replace(",", "."));
  if (!Number.isFinite(value) || value <= 0) return 0;
  return match[2].toLowerCase() === "kg" ? value * 1000 : value;
}

function getProductKaratValue(product: any): number | null {
  const attrs = parseProductAttributes(product);
  const directCandidates = [
    product?.karat,
    product?.carat,
    attrs?.karat,
    attrs?.carat,
  ];
  for (const candidate of directCandidates) {
    const value = Number(candidate);
    if (Number.isFinite(value) && value > 0) return value;
  }
  const haystack = `${product?.name || ""} ${product?.description || ""}`;
  const match = haystack.match(/\b(18|22|24)\s*k\b/i);
  if (!match) return null;
  const value = Number.parseInt(match[1], 10);
  return Number.isFinite(value) ? value : null;
}

function formatGoldWeightLabel(weightGrams: number | null | undefined) {
  if (!weightGrams || !Number.isFinite(weightGrams)) return "";
  if (weightGrams >= 1000 && weightGrams % 1000 === 0)
    return `${weightGrams / 1000}kg`;
  return `${weightGrams}g`;
}

function getProductPurityLabel(product: any): string {
  const attrs = parseProductAttributes(product);
  const directLabel = String(
    product?.purityLabel ||
      attrs?.purityLabel ||
      product?.purity ||
      attrs?.purity ||
      product?.fineness ||
      attrs?.fineness ||
      product?.purityPercent ||
      attrs?.purityPercent ||
      "",
  ).trim();
  if (directLabel) return directLabel;

  const karat = getProductKaratValue(product);
  if (karat) return `${karat}K`;
  if (getGoldCategory(product) === "dore") return "Doré contrôlé";
  return "Or certifié";
}

