  type GeoCountry = { id: number; code: string; name: string };
  type GeoRegion = { id: number; name: string };
  type GeoCity = {
    id: number;
    name: string;
    latitude?: string | null;
    longitude?: string | null;
  };
  type ActiveGeo = {
    country: GeoCountry | null;
    region: GeoRegion | null;
    city: GeoCity | null;
    source: "gps" | "ip" | "manual" | "stored";
  };

  const savedGeo = (() => {
    try {
      const raw = localStorage.getItem("marketplace_location_v1");
      if (!raw) return null;
      const parsed = JSON.parse(raw) as any;
      if (!parsed || typeof parsed !== "object") return null;
      if (!Number.isFinite(parsed.lat) || !Number.isFinite(parsed.lng))
        return null;
      if (
        isRayonTenant &&
        parsed.source !== "gps" &&
        !isWithinBeninBounds(parsed.lat, parsed.lng)
      ) {
        return {
          ...parsed,
          lat: RAYON_SHOWCASE_LOCATION.lat,
          lng: RAYON_SHOWCASE_LOCATION.lon,
          label: RAYON_SHOWCASE_LOCATION.label,
          source: "ip",
        };
      }
      return parsed;
    } catch {
      return null;
    }
  })();

  const cachedBdoLocation = (() => {
    const cached = getCachedBdoLocation();
    if (
      isRayonTenant &&
      cached &&
      cached.source !== "gps" &&
      !isWithinBeninBounds(cached.lat, cached.lon)
    ) {
      return {
        ...cached,
        lat: RAYON_SHOWCASE_LOCATION.lat,
        lon: RAYON_SHOWCASE_LOCATION.lon,
        source: "ip" as const,
      };
    }
    return cached;
  })();

  const locationToastShownRef = useRef(false);

  const normalizedSavedSource: ActiveGeo["source"] =
    savedGeo?.source === "manual"
      ? "manual"
      : savedGeo?.source === "device" || savedGeo?.source === "gps"
        ? "gps"
        : savedGeo?.source === "ip"
          ? "ip"
          : "stored";

  const initialSource: LocationSource =
    cachedBdoLocation?.source ??
    (normalizedSavedSource === "gps" || normalizedSavedSource === "manual"
      ? normalizedSavedSource
      : "ip");

