  const categories = allowedCategories.map((slug) => {
    const meta = getCategoryMeta(slug);
    return {
      id: slug,
      slug,
      name: meta.label,
      icon: meta.icon,
      color: meta.accent,
    };
  });

  const getCategoryChipLabel = (label: string) => {
    const cleaned = String(label || "")
      .replace(/\s+/g, " ")
      .trim();
    const parts = cleaned
      .split("/")
      .map((p) => p.trim())
      .filter(Boolean);
    if (parts.length < 2) return cleaned;
    const isFrench = String(language || "")
      .toLowerCase()
      .startsWith("fr");
    return isFrench ? parts[1] : parts[0];
  };

  const resolveCategorySlugByKeywords = (...keywords: string[]) => {
    const normalizedKeywords = keywords
      .map((value) => normalizeCategorySlug(value))
      .filter((value): value is string => Boolean(value));
    if (!normalizedKeywords.length) return null;
    for (const category of categories) {
      const candidates = [
        normalizeCategorySlug(category.slug),
        normalizeCategorySlug(category.name),
      ].filter((value): value is string => Boolean(value));
      if (
        normalizedKeywords.some((keyword) =>
          candidates.some(
            (candidate) =>
              candidate === keyword ||
              candidate.includes(keyword) ||
              keyword.includes(candidate),
          ),
        )
      ) {
        return category.slug;
      }
    }
    return null;
  };

  const hozJewelryCategorySlug = resolveCategorySlugByKeywords(
    "jewelry",
    "ring",
    "bracelet",
    "pendant",
    "chain",
  );
  const hozCoutureCategorySlug = resolveCategorySlugByKeywords(
    "couture",
    "fashion",
    "garment",
    "apparel",
    "capsule",
  );
  const hozCollectiblesCategorySlug = resolveCategorySlugByKeywords(
    "collectible",
    "collectibles",
    "cultural",
    "object",
    "objects",
    "art",
  );

  const updateCategoryChipsUiState = useCallback(() => {
    if (typeof window === "undefined") return;
    const el = categoryChipsRef.current;
    if (!el) return;

    const maxScroll = Math.max(0, el.scrollWidth - el.clientWidth);
    const overflow = maxScroll > 4;
    const atStart = !overflow || el.scrollLeft <= 1;
    const atEnd =
      !overflow || el.scrollLeft + el.clientWidth >= el.scrollWidth - 1;

    setCategoryChipsUi((prev) => {
      if (
        prev.atStart === atStart &&
        prev.atEnd === atEnd &&
        prev.overflow === overflow
      )
        return prev;
      return { atStart, atEnd, overflow };
    });
  }, []);

  const scrollCategoryChipsBy = useCallback((direction: 1 | -1) => {
    if (typeof window === "undefined") return;
    const el = categoryChipsRef.current;
    if (!el) return;

    const first =
      el.querySelector<HTMLElement>("button") ??
      (el.firstElementChild as HTMLElement | null);
    const chipWidth = first ? first.getBoundingClientRect().width : 140;
    const styles = window.getComputedStyle(el);
    const gapRaw = parseFloat(styles.columnGap || styles.gap || "8");
    const gap = Number.isFinite(gapRaw) ? gapRaw : 8;
    const delta = (chipWidth + gap) * 3;

    el.scrollTo({
      left: el.scrollLeft + direction * delta,
      behavior: "smooth",
    });
  }, []);

  useEffect(() => {
    const el = categoryChipsRef.current;
    if (!el) return;

    updateCategoryChipsUiState();

    const onScroll = () => updateCategoryChipsUiState();
    el.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    return () => {
      el.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, [categories.length, updateCategoryChipsUiState]);

