    if (!showProducts) setShowProducts(true);
    if (mapOverlayOpen) setMapOverlayOpen(false);
    if (selectedShop) setSelectedShop(null);
    if (selectedMachinery) setSelectedMachinery(null);
    if (selectedOpportunity) setSelectedOpportunity(null);
